U['A1-U08-L05'] = None  # 60 كلمة على الأقلّ أصلًا — فوق المواصفة، يُترك كما هو

def main():
    ok = True
    for u in range(1, 9):
        code = f'A1-U0{u}'; path = os.path.join(PACKS, f'iqra-pack-{code}.json'); pack = json.load(open(path, encoding='utf-8')); out = {}
        for l in pack['lessons']:
            if l['code'] not in U or U[l['code']] is None: continue
            o = U[l['code']]; p = l['content']['produce']
            for k in ('goal_ar', 'can_do_ar', 'can_do_en'):
                for a, b in GOAL_SUBS: l[k] = l[k].replace(a, b)
            p['prompt_ar'] = o['prompt']; p['checklist'] = o['check']
            if o['model'] is not None: p['model_ar'] = o['model']
            if o.get('minw'): p['min_words'] = max(int(p.get('min_words') or 0), o['minw'])
            kind = p['kind']; m = p['model_ar']; n = wc(m if l['code'] != 'A1-U07-L05' else m.split('\n\n')[1])
            lo, hi = (40, 62) if kind == 'write' else (70, 110)   # تحدّث A1 ≈ 70 كلمة/د → 60–90 ث ≈ 70–105 كلمة
            flag = '' if lo <= n <= hi else '  !! out of range'
            if flag: ok = False
            assert len(p['checklist']) <= 8 and all(len(c) <= 200 for c in p['checklist']) and len(m) <= 4000 and len(p['prompt_ar']) <= 900
            print(f"{l['code']} {kind:5} model {n:3} w · {len(m)} ch · check {len(p['checklist'])} · min {p.get('min_words')}{flag}")
            out[l['code']] = {'goal_ar': l['goal_ar'], 'can_do_ar': l['can_do_ar'], 'can_do_en': l['can_do_en'], 'produce': p}
        json.dump(pack, open(path, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
        json.dump(out, open(os.path.join(HERE, f'{code}.json'), 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    print('ALL OK' if ok else 'CHECK FLAGS')

if __name__ == '__main__': main()
